<script>
  (() => { const modal=document.getElementById('po-modal'); const details=document.getElementById('po-trip-details'); const close=modal.querySelector('.po-close'); const hide=()=>{modal.classList.remove('is-open');document.body.style.overflow='';}; document.querySelectorAll('[data-po-modal]').forEach(trigger=>trigger.addEventListener('click',event=>{event.preventDefault();details.textContent=trigger.closest('.trip-line').querySelector('.trip-route').textContent.trim()+' · '+trigger.closest('.trip-line').querySelector('.trip-code').textContent.trim();modal.classList.add('is-open');document.body.style.overflow='hidden';close.focus();})); close.addEventListener('click',hide); modal.addEventListener('click',event=>{if(event.target===modal)hide();}); const detailModal=document.getElementById('trip-detail-modal'); const detailContent=document.getElementById('trip-detail-content'); const detailClose=detailModal.querySelector('.po-close'); const hideDetail=()=>{detailModal.classList.remove('is-open');document.body.style.overflow='';}; document.querySelectorAll('[data-detail-modal]').forEach(trigger=>trigger.addEventListener('click',()=>{const card=trigger.closest('.trip-line'); detailContent.textContent=card.querySelector('.trip-route').textContent.trim()+' · '+card.querySelector('.trip-code').textContent.trim()+' · '+Array.from(card.querySelectorAll('.trip-meta .badge')).map(item=>item.textContent.trim()).join(' · '); detailModal.classList.add('is-open');document.body.style.overflow='hidden';detailClose.focus();})); detailClose.addEventListener('click',hideDetail); detailModal.querySelector('[data-detail-close]').addEventListener('click',hideDetail); detailModal.addEventListener('click',event=>{if(event.target===detailModal)hideDetail();}); document.addEventListener('keydown',event=>{if(event.key==='Escape'){hide();hideDetail();}}); })();
